from collections import defaultdict


def left_join(left: list[dict], right: list[dict], on: str) -> list[dict]:
    index: dict[object, list[dict]] = defaultdict(list)
    right_columns: dict[str, None] = {}
    for row in right:
        for col in row:
            if col != on:
                right_columns.setdefault(col)
        if row.get(on) is not None:
            index[row[on]].append(row)

    def merge(l_row: dict, r_row: dict) -> dict:
        out = dict(l_row)
        for col, val in r_row.items():
            if col == on:
                continue
            out[f"{col}_right" if col in l_row else col] = val
        return out

    result: list[dict] = []
    for row in left:
        matches = index.get(row.get(on)) if row.get(on) is not None else None
        if matches:
            result.extend(merge(row, m) for m in matches)
        else:
            result.append(merge(row, dict.fromkeys(right_columns)))
    return result
